//! End-to-end test for the placeholder API gap (python-pptx parity).
//!
//! Before v0.2.36 follow-up, the active slide XML emitter produced bare
//! `<p:nvPr/>` for title and body shapes — meaning PowerPoint saw them as
//! regular shapes, not as fills of the layout's intended title/body
//! placeholders. The layout's master title placeholder stayed empty even
//! when the user set `SlideContent::new("Title")`.
//!
//! These tests build a deck, unzip the slide XML, and assert that the
//! expected `<p:ph type="..."/>` elements are present.

use ppt_rs::{Presentation, SlideContent, SlideLayout, create_pptx_with_content};
use std::io::Read as _;

fn slide_xml(bytes: &[u8], slide_index: usize) -> String {
    let cursor = std::io::Cursor::new(bytes);
    let mut archive = zip::ZipArchive::new(cursor).unwrap();
    let name = format!("ppt/slides/slide{}.xml", slide_index + 1);
    let mut s = String::new();
    archive
        .by_name(&name)
        .unwrap_or_else(|_| panic!("missing {name}"))
        .read_to_string(&mut s)
        .unwrap();
    s
}

#[test]
fn title_and_content_layout_emits_placeholders() {
    let slides = vec![SlideContent::new("Roadmap")
        .add_bullet("Q1")
        .add_bullet("Q2")];
    let bytes = create_pptx_with_content("Demo", slides).unwrap();
    let xml = slide_xml(&bytes, 0);
    assert!(
        xml.contains(r#"<p:ph type="title"/>"#),
        "title placeholder missing — got:\n{xml}"
    );
    assert!(
        xml.contains(r#"<p:ph type="body" idx="1"/>"#),
        "body placeholder missing — got:\n{xml}"
    );
}

#[test]
fn title_only_emits_only_title_placeholder() {
    let slides = vec![SlideContent::new("Section")
        .layout(SlideLayout::TitleOnly)];
    let bytes = create_pptx_with_content("Demo", slides).unwrap();
    let xml = slide_xml(&bytes, 0);
    assert!(xml.contains(r#"<p:ph type="title"/>"#));
    assert!(!xml.contains(r#"<p:ph type="body""#));
}

#[test]
fn centered_title_uses_ctr_title_placeholder() {
    let slides = vec![SlideContent::new("Big")
        .layout(SlideLayout::CenteredTitle)];
    let bytes = create_pptx_with_content("Demo", slides).unwrap();
    let xml = slide_xml(&bytes, 0);
    assert!(xml.contains(r#"<p:ph type="ctrTitle"/>"#));
}

#[test]
fn two_column_emits_two_body_placeholders() {
    let slides = vec![SlideContent::new("Compare")
        .add_bullet("A")
        .add_bullet("B")
        .add_bullet("C")
        .add_bullet("D")
        .layout(SlideLayout::TwoColumn)];
    let bytes = create_pptx_with_content("Demo", slides).unwrap();
    let xml = slide_xml(&bytes, 0);
    assert!(xml.contains(r#"<p:ph type="title"/>"#));
    assert!(xml.contains(r#"<p:ph type="body" idx="1"/>"#));
    assert!(xml.contains(r#"<p:ph type="body" idx="2"/>"#));
}

#[test]
fn presentation_builder_pipeline_also_emits_placeholders() {
    // The Presentation::build() path must use the same emitter as
    // create_pptx_with_content, so high-level users get placeholders too.
    let bytes = Presentation::new()
        .title("High-level demo")
        .add_slide(SlideContent::new("Hello").add_bullet("World"))
        .build()
        .unwrap();
    let xml = slide_xml(&bytes, 0);
    assert!(xml.contains(r#"<p:ph type="title"/>"#));
    assert!(xml.contains(r#"<p:ph type="body" idx="1"/>"#));
}

#[test]
fn package_validation_still_passes_with_placeholders() {
    // Adding `<p:ph type="..."/>` must not break the zero-repair validation gate.
    let bytes = create_pptx_with_content(
        "Validate me",
        vec![SlideContent::new("Title").add_bullet("Bullet")],
    )
    .unwrap();
    let report = ppt_rs::validate_package_bytes(&bytes);
    let errors: Vec<_> = report
        .issues
        .iter()
        .filter(|i| matches!(i.severity, ppt_rs::ValidationSeverity::Error))
        .collect();
    assert!(
        errors.is_empty(),
        "placeholder XML regressed package validation: {errors:?}"
    );
}

use ppt_rs::api::Presentation;
use ppt_rs::export::image_export::{ImageExportOptions, ImageFormat};
use ppt_rs::generator::SlideContent;
use ppt_rs::opc::compress::{CompressionLevel, CompressionOptions};
use std::fs;
use std::path::Path;

#[test]
fn test_html_export_with_section_grouping() {
    use ppt_rs::export::html::HtmlExportOptions;

    let pres = Presentation::new()
        .title("Sectioned")
        .add_section("Intro", 0, 1)
        .unwrap()
        .add_slide(SlideContent::new("Slide 1").add_bullet("Point"));

    let output_path = "test_export_sections.html";
    pres.save_as_html_with_options(
        output_path,
        &HtmlExportOptions::new().with_section_grouping(true),
    )
    .unwrap();

    let content = fs::read_to_string(output_path).unwrap();
    assert!(content.contains("section-label"));
    assert!(content.contains("Intro"));

    fs::remove_file(output_path).unwrap();
}

#[test]
fn test_html_export_api() {
    let pres = Presentation::new()
        .title("HTML Export Test")
        .add_slide(SlideContent::new("Slide 1").add_bullet("Item 1"));

    let output_path = "test_export.html";
    pres.save_as_html(output_path).unwrap();

    assert!(Path::new(output_path).exists());
    let content = fs::read_to_string(output_path).unwrap();
    assert!(content.contains("HTML Export Test"));
    assert!(content.contains("Slide 1"));
    assert!(content.contains("Item 1"));

    fs::remove_file(output_path).unwrap();
}

#[test]
fn test_from_path_api() {
    // First create a pptx
    let pres = Presentation::new()
        .title("Import Test")
        .add_slide(SlideContent::new("Slide 1").add_bullet("Item 1"));

    let pptx_path = "test_import_api.pptx";
    pres.save(pptx_path).unwrap();

    // Then import it using from_path
    let imported = Presentation::from_path(pptx_path).unwrap();

    assert_eq!(imported.get_title(), "Import Test");
    assert_eq!(imported.slide_count(), 1);

    fs::remove_file(pptx_path).unwrap();
}

#[test]
fn test_pdf_export_api() {
    let pres = Presentation::new()
        .title("PDF Export Test")
        .add_slide(SlideContent::new("Slide 1"));

    let output_path = "test_export.pdf";

    // Pure-Rust vector rendering — no external binaries required
    pres.save_as_pdf(output_path).unwrap();
    assert!(Path::new(output_path).exists());
    let bytes = fs::read(output_path).unwrap();
    assert_eq!(&bytes[..5], b"%PDF-");
    fs::remove_file(output_path).unwrap();
}

#[cfg(feature = "pdf-native")]
#[test]
fn test_pdf_export_via_pdfrs_api() {
    let pres = Presentation::new()
        .title("PDF Native Test")
        .add_slide(SlideContent::new("Slide 1").add_bullet("Bullet"));

    let output_path = "test_export_native.pdf";
    let options = ppt_rs::PdfExportOptions::new()
        .with_frontmatter(false)
        .with_notes(false);

    pres.save_as_pdf_via_pdfrs(output_path, &options).unwrap();
    assert!(Path::new(output_path).exists());
    let bytes = fs::read(output_path).unwrap();
    assert_eq!(&bytes[..5], b"%PDF-");
    assert!(pdfrs::pdf::validate_pdf_bytes(&bytes).valid);
    fs::remove_file(output_path).unwrap();
}

#[cfg(feature = "pdf-native")]
#[test]
fn test_to_pdf_bytes_api() {
    let pres = Presentation::new()
        .title("Bytes")
        .add_slide(SlideContent::new("S1").add_bullet("Hi"));

    let bytes = pres
        .to_pdf_bytes(&ppt_rs::PdfExportOptions::default())
        .unwrap();
    assert_eq!(&bytes[..5], b"%PDF-");
    assert!(pdfrs::pdf::validate_pdf_bytes(&bytes).valid);
}

#[test]
fn test_png_export_api() {
    let pres = Presentation::new()
        .title("PNG Export Test")
        .add_slide(SlideContent::new("Slide 1"));

    let output_dir = "test_export_png";

    // This test requires pdftoppm (poppler) to be installed
    match pres.save_as_png(output_dir) {
        Ok(_) => {
            assert!(Path::new(output_dir).exists());
            // Should have at least one image
            let count = fs::read_dir(output_dir).unwrap().count();
            assert!(count > 0);
            fs::remove_dir_all(output_dir).unwrap();
        }
        Err(e) => {
            // Skip test if required tools are not available
            println!("Skipping PNG export test (pdftoppm required): {}", e);
        }
    }
}

#[test]
fn test_from_pdf_api() {
    // This test requires pdftoppm and a PDF file to be present
    let pdf_path = "test_import.pdf";

    if !Path::new(pdf_path).exists() {
        println!("Skipping PDF import test: test_import.pdf not found");
        return;
    }

    match Presentation::from_pdf(pdf_path) {
        Ok(pres) => {
            assert!(pres.slide_count() > 0);
        }
        Err(e) => {
            println!("Skipping PDF import test (pdftoppm required): {}", e);
        }
    }
}

#[test]
fn test_markdown_export_api() {
    let pres = Presentation::new()
        .title("Markdown API Test")
        .add_slide(SlideContent::new("Slide 1").add_bullet("Item 1"))
        .add_slide(
            SlideContent::new("Slide 2")
                .add_bullet("Item A")
                .add_bullet("Item B"),
        );

    let output_path = "test_api_export.md";
    pres.save_as_markdown(output_path).unwrap();

    assert!(Path::new(output_path).exists());
    let content = fs::read_to_string(output_path).unwrap();

    assert!(content.contains("# Markdown API Test"));
    assert!(content.contains("Slide 1"));
    assert!(content.contains("Slide 2"));
    assert!(content.contains("- Item 1"));
    assert!(content.contains("---"));

    fs::remove_file(output_path).unwrap();
}

#[test]
fn test_markdown_export_with_options_api() {
    let pres = Presentation::new()
        .title("Options API Test")
        .add_slide(SlideContent::new("Test Slide").add_bullet("Point"));

    let options = ppt_rs::export::md::MarkdownOptions::new()
        .with_slide_numbers(false)
        .with_frontmatter(false);

    let output_path = "test_api_options.md";
    pres.save_as_markdown_with_options(output_path, &options)
        .unwrap();

    let content = fs::read_to_string(output_path).unwrap();

    // Without options, these should not be present
    assert!(!content.contains("## Slide 1:"));
    assert!(!content.contains("title:"));

    fs::remove_file(output_path).unwrap();
}

#[test]
fn test_image_export_api() {
    let pres = Presentation::new()
        .title("Image Export API")
        .add_slide(SlideContent::new("Slide 1"))
        .add_slide(SlideContent::new("Slide 2"))
        .add_slide(SlideContent::new("Slide 3"));

    let output_dir = "test_api_images";
    let options = ImageExportOptions::new()
        .with_format(ImageFormat::Png)
        .with_dpi(96);

    // This test requires pdftoppm (poppler) to be installed
    match pres.save_as_images(output_dir, &options) {
        Ok(paths) => {
            assert_eq!(paths.len(), 3, "one image per slide");
            for (i, path) in paths.iter().enumerate() {
                assert!(path.exists(), "missing {}", path.display());
                assert!(
                    path.file_name()
                        .is_some_and(|n| n.to_string_lossy() == format!("Slide{}.png", i + 1)),
                    "unexpected name: {}",
                    path.display()
                );
            }
            // Cleanup
            let _ = fs::remove_dir_all(output_dir);
        }
        Err(e) => {
            println!("Skipping image export test (pdftoppm required): {}", e);
        }
    }
}

#[test]
fn test_slide_image_export_api() {
    let pres = Presentation::new()
        .title("Single Slide Export")
        .add_slide(SlideContent::new("Slide 1"))
        .add_slide(SlideContent::new("Slide 2"));

    let output_path = "test_single_slide.png";
    let options = ImageExportOptions::new()
        .with_format(ImageFormat::Png)
        .with_slide(1);

    // This test requires pdftoppm (poppler) to be installed
    match pres.save_slide_as_image(1, output_path, &options) {
        Ok(path) => {
            assert!(path.exists());
            fs::remove_file(output_path).unwrap();
        }
        Err(e) => {
            println!(
                "Skipping single slide export test (pdftoppm required): {}",
                e
            );
        }
    }
}

#[test]
fn test_thumbnail_export_api() {
    let pres = Presentation::new()
        .title("Thumbnail Test")
        .add_slide(SlideContent::new("Title Slide"));

    let output_path = "test_thumbnail.png";

    // This test requires pdftoppm (poppler) to be installed
    match pres.save_thumbnail(output_path, 300) {
        Ok(_) => {
            assert!(Path::new(output_path).exists());
            fs::remove_file(output_path).unwrap();
        }
        Err(e) => {
            println!("Skipping thumbnail export test (pdftoppm required): {}", e);
        }
    }
}

#[test]
fn test_compression_api_basic() {
    let pres = Presentation::new()
        .title("Compression API")
        .add_slide(SlideContent::new("Slide 1").add_bullet("Point"))
        .add_slide(SlideContent::new("Slide 2").add_bullet("Point"));

    let output_path = "test_api_compressed.pptx";
    let options = CompressionOptions::new().with_level(CompressionLevel::Light);

    let result = pres.compress(output_path, &options).unwrap();

    assert!(Path::new(output_path).exists());
    assert!(result.original_size > 0);
    assert!(result.compressed_size > 0);
    assert!(result.reduction_percent >= 0.0);

    fs::remove_file(output_path).unwrap();
}

#[test]
fn test_analyze_size_api() {
    let pres = Presentation::new()
        .title("Analysis API")
        .add_slide(SlideContent::new("Slide 1"))
        .add_slide(SlideContent::new("Slide 2"));

    let analysis = pres.analyze_size().unwrap();

    assert!(analysis.total_size > 0);
    assert_eq!(analysis.slide_count, 2);

    let summary = analysis.summary();
    assert!(summary.contains("PPTX Analysis"));
    assert!(summary.contains("2"));
}

#[test]
fn test_compression_preset_api() {
    let pres = Presentation::new()
        .title("Preset API")
        .add_slide(SlideContent::new("Test"));

    // Test web preset
    let web_opts = CompressionOptions::web();
    let web_result = pres.compress("test_web_preset.pptx", &web_opts).unwrap();
    assert!(web_result.original_size > 0);

    // Test maximum preset
    let max_opts = CompressionOptions::maximum();
    let max_result = pres.compress("test_max_preset.pptx", &max_opts).unwrap();
    assert!(max_result.original_size > 0);

    // Cleanup
    let _ = fs::remove_file("test_web_preset.pptx");
    let _ = fs::remove_file("test_max_preset.pptx");
}

#[test]
fn test_image_export_options_presets() {
    let hq = ImageExportOptions::high_quality();
    assert_eq!(hq.dpi, 300);
    assert_eq!(hq.format, ImageFormat::Png);

    let web = ImageExportOptions::web_optimized();
    assert_eq!(web.dpi, 96);
    assert_eq!(web.format, ImageFormat::Jpeg);
    assert_eq!(web.jpeg_quality, 85);
}

//! MCP server integration tests
//!
//! Tests the ppt_mcp binary end-to-end over stdio JSON-RPC transport.

use std::io::{BufRead, Write};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};

use serial_test::serial;

/// Keeps the MCP subprocess alive until the test ends, then kills it (avoids zombies / races).
struct ChildGuard(Option<Child>);

impl Drop for ChildGuard {
    fn drop(&mut self) {
        if let Some(mut child) = self.0.take() {
            let _ = child.kill();
            let _ = child.wait();
        }
    }
}

fn start_server() -> (ChildGuard, ChildStdin, std::io::BufReader<ChildStdout>) {
    let mut child = Command::new(env!("CARGO_BIN_EXE_ppt_mcp"))
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::null())
        .spawn()
        .expect("Failed to start ppt_mcp");

    let stdin = child.stdin.take().expect("Failed to get stdin");
    let stdout = child.stdout.take().expect("Failed to get stdout");
    let reader = std::io::BufReader::new(stdout);

    (ChildGuard(Some(child)), stdin, reader)
}

fn send(stdin: &mut ChildStdin, id: u64, method: &str, params: serde_json::Value) {
    let msg = serde_json::json!({
        "jsonrpc": "2.0",
        "id": id,
        "method": method,
        "params": params,
    });
    writeln!(stdin, "{}", serde_json::to_string(&msg).unwrap()).unwrap();
    stdin.flush().unwrap();
}

fn recv(reader: &mut std::io::BufReader<ChildStdout>) -> serde_json::Value {
    let mut line = String::new();
    reader
        .read_line(&mut line)
        .expect("Failed to read response");
    let trimmed = line.trim();
    assert!(
        !trimmed.is_empty(),
        "empty MCP stdout line (ppt_mcp may have exited early); build with `cargo test --features mcp --test mcp_integration_test`"
    );
    serde_json::from_str(trimmed).expect("Failed to parse JSON response")
}

/// rmcp expects a spec-compliant `initialize` payload (see MCP handshake).
fn init_params() -> serde_json::Value {
    serde_json::json!({
        "protocolVersion": "2024-11-05",
        "capabilities": {},
        "clientInfo": {
            "name": "ppt-rs-integration-test",
            "version": "1.0.0"
        }
    })
}

fn notify_initialized(stdin: &mut ChildStdin) {
    let msg = serde_json::json!({
        "jsonrpc": "2.0",
        "method": "notifications/initialized",
        "params": {}
    });
    writeln!(stdin, "{}", serde_json::to_string(&msg).unwrap()).unwrap();
    stdin.flush().unwrap();
}

fn handshake(stdin: &mut ChildStdin, reader: &mut std::io::BufReader<ChildStdout>) {
    send(stdin, 1, "initialize", init_params());
    let _ = recv(reader);
    notify_initialized(stdin);
}

fn tmp_path(name: &str) -> String {
    let dir = std::env::temp_dir().join("ppt_rs_mcp_integration");
    let _ = std::fs::create_dir_all(&dir);
    dir.join(format!("ppt_mcp_test_{name}"))
        .to_string_lossy()
        .into_owned()
}

fn cleanup(path: &str) {
    let _ = std::fs::remove_file(path);
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[test]
#[serial]
fn test_initialize() {
    let (_guard, mut stdin, mut reader) = start_server();
    send(&mut stdin, 1, "initialize", init_params());
    let resp = recv(&mut reader);

    assert_eq!(resp["id"], 1);
    assert_eq!(resp["result"]["protocolVersion"], "2024-11-05");
    assert_eq!(resp["result"]["serverInfo"]["name"], "ppt-rs");
    assert!(resp["result"]["capabilities"]["tools"].is_object());
}

#[test]
#[serial]
fn test_tools_list() {
    let (_guard, mut stdin, mut reader) = start_server();
    handshake(&mut stdin, &mut reader);

    send(&mut stdin, 2, "tools/list", serde_json::json!({}));
    let resp = recv(&mut reader);

    assert_eq!(resp["id"], 2);
    let tools = resp["result"]["tools"].as_array().unwrap();
    assert!(tools.len() >= 12);

    let names: Vec<&str> = tools.iter().map(|t| t["name"].as_str().unwrap()).collect();
    assert!(names.contains(&"create_presentation"));
    assert!(names.contains(&"markdown_to_pptx"));
    assert!(names.contains(&"get_pptx_info"));
    assert!(names.contains(&"export_pptx"));
    assert!(names.contains(&"merge_pptx"));
    assert!(names.contains(&"validate_pptx"));
    assert!(names.contains(&"create_presentation_with_tables"));
    assert!(names.contains(&"create_presentation_with_charts"));
    assert!(names.contains(&"compress_pptx"));
    assert!(names.contains(&"repair_pptx"));
    assert!(names.contains(&"apply_theme"));
    assert!(names.contains(&"diff_pptx"));

    for tool in tools {
        assert!(tool["name"].is_string());
        assert!(tool["description"].is_string());
        assert!(tool["inputSchema"]["type"] == "object");
        assert!(tool["inputSchema"]["properties"].is_object());
    }
}

#[test]
#[serial]
fn test_method_not_found() {
    let (_guard, mut stdin, mut reader) = start_server();
    handshake(&mut stdin, &mut reader);
    send(&mut stdin, 2, "nonexistent_method", serde_json::json!({}));
    let resp = recv(&mut reader);

    assert_eq!(resp["id"], 2);
    assert_eq!(resp["error"]["code"], -32601);
}

#[test]
#[serial]
fn test_create_presentation() {
    let path = tmp_path("create.pptx");
    cleanup(&path);

    let (_guard, mut stdin, mut reader) = start_server();
    handshake(&mut stdin, &mut reader);

    send(
        &mut stdin,
        2,
        "tools/call",
        serde_json::json!({
            "name": "create_presentation",
            "arguments": {
                "title": "MCP Test",
                "output_path": &path,
                "slides": [
                    { "title": "Slide 1", "bullets": ["Hello", "World"] },
                    { "title": "Slide 2", "bullets": ["Alpha", "Beta"] },
                ]
            }
        }),
    );
    let resp = recv(&mut reader);

    assert_eq!(resp["id"], 2);
    assert!(!resp["result"]["isError"].as_bool().unwrap_or(false));
    let text = resp["result"]["content"][0]["text"].as_str().unwrap();
    assert!(text.contains("Created presentation"));
    assert!(text.contains("2 slide(s)"));
    assert!(std::path::Path::new(&path).exists());

    cleanup(&path);
}

#[test]
#[serial]
fn test_create_presentation_empty_slides_error() {
    let (_guard, mut stdin, mut reader) = start_server();
    handshake(&mut stdin, &mut reader);

    send(
        &mut stdin,
        2,
        "tools/call",
        serde_json::json!({
            "name": "create_presentation",
            "arguments": {
                "title": "Empty",
                "output_path": "/tmp/never.pptx",
                "slides": []
            }
        }),
    );
    let resp = recv(&mut reader);

    assert_eq!(resp["id"], 2);
    assert!(resp["result"]["isError"].as_bool().unwrap_or(false));
    assert!(
        resp["result"]["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("No slides")
    );
}

#[test]
#[serial]
fn test_markdown_to_pptx() {
    let path = tmp_path("md.pptx");
    cleanup(&path);

    let (_guard, mut stdin, mut reader) = start_server();
    handshake(&mut stdin, &mut reader);

    send(
        &mut stdin,
        2,
        "tools/call",
        serde_json::json!({
            "name": "markdown_to_pptx",
            "arguments": {
                "markdown": "# Intro\n- Point 1\n- Point 2\n\n# Summary\n- Done\n",
                "output_path": &path,
                "title": "MD Test"
            }
        }),
    );
    let resp = recv(&mut reader);

    assert_eq!(resp["id"], 2);
    assert!(!resp["result"]["isError"].as_bool().unwrap_or(false));
    assert!(
        resp["result"]["content"][0]["text"]
            .as_str()
            .unwrap()
            .contains("2 slide(s)")
    );
    assert!(std::path::Path::new(&path).exists());

    cleanup(&path);
}

#[test]
#[serial]
fn test_markdown_to_pptx_missing_param() {
    let (_guard, mut stdin, mut reader) = start_server();
    handshake(&mut stdin, &mut reader);

    send(
        &mut stdin,
        2,
        "tools/call",
        serde_json::json!({
            "name": "markdown_to_pptx",
            "arguments": {
                "output_path": "/tmp/never.pptx"
            }
        }),
    );
    let resp = recv(&mut reader);

    // rmcp 2.2.0 returns missing-param as a tool-level error (isError),
    // not a JSON-RPC -32602 error.
    assert!(
        resp["result"]["isError"].as_bool().unwrap_or(false),
        "expected isError for missing param; got: {resp}"
    );
}

