        .add_slide(
            SlideContent::new("First Slide")
                .add_bullet("Bullet 1")
                .add_bullet("Bullet 2"),
        )
        .add_slide(SlideContent::new("Second Slide").add_bullet("Another point"));

    let html = export_to_html(&pres).expect("Failed to export HTML");

    assert!(html.contains("<!DOCTYPE html>"));
    assert!(html.contains("<title>HTML Export Test</title>"));
    assert!(html.contains("<h1>HTML Export Test</h1>"));
    assert!(html.contains("<h2>First Slide</h2>"));
    assert!(html.contains("Bullet 1"));
    assert!(html.contains("<h2>Second Slide</h2>"));
    assert!(html.contains(".slide {")); // CSS check
}

#[test]
fn test_html_export_with_options() {
    let pres = Presentation::with_title("Enhanced Export Test")
        .add_slide(
            SlideContent::new("Slide with Notes")
                .add_bullet("Point 1")
                .add_bullet("Point 2"),
        )
        .add_slide(SlideContent::new("Another Slide").add_bullet("More content"));

    // Add notes to first slide
    let mut slide_with_notes = SlideContent::new("Slide with Notes")
        .add_bullet("Point 1")
        .add_bullet("Point 2");
    slide_with_notes.notes = Some("Speaker notes here".to_string());

    let options = HtmlExportOptions::new()
        .with_notes(true)
        .with_navigation(true)
        .with_syntax_highlight(false);

    let html =
        export_to_html_with_options(&pres, &options).expect("Failed to export HTML with options");

    // Check for enhanced features
    assert!(html.contains("navigation-controls")); // Navigation should be included
    assert!(html.contains("slideCounter")); // Counter functionality (JavaScript variable)
    assert!(html.contains("addEventListener")); // Event listeners for navigation
    assert!(html.contains("speaker-notes")); // Notes styling
}

//! Integration tests for batch pipeline conversion.

use std::io::Write;
use std::path::Path;

use ppt_rs::{BatchJob, BatchOptions, InputFormat, convert_file, run_batch};

fn write_file(dir: &Path, name: &str, body: &str) -> std::path::PathBuf {
    let path = dir.join(name);
    std::fs::File::create(&path)
        .unwrap()
        .write_all(body.as_bytes())
        .unwrap();
    path
}

#[test]
fn batch_converts_html_file() {
    let root = std::env::temp_dir().join(format!("ppt_rs_pipe_html_{}", std::process::id()));
    let output = root.join("out");
    std::fs::create_dir_all(&root).unwrap();

    let input = write_file(
        &root,
        "page.html",
        "<h1>Title</h1><p>Body</p><h2>Section</h2><ul><li>One</li></ul>",
    );

    let job = BatchJob::new(&input);
    let results = run_batch(
        &[job],
        &BatchOptions::new(&output),
    )
    .unwrap();

    assert_eq!(results.len(), 1);
    assert!(results[0].output.exists());
    assert!(results[0].slide_count >= 1);
    assert!(results[0].bytes > 1000);

    let _ = std::fs::remove_dir_all(&root);
}

#[cfg(feature = "cli")]
#[test]
fn batch_converts_markdown_file() {
    let root = std::env::temp_dir().join(format!("ppt_rs_pipe_md_{}", std::process::id()));
    let output = root.join("out");
    std::fs::create_dir_all(&root).unwrap();

    let input = write_file(
        &root,
        "deck.md",
        "# Slide A\n\n- Alpha\n\n# Slide B\n\n- Beta",
    );

    let result = convert_file(
        &BatchJob::new(&input),
        &BatchOptions::new(&output),
        InputFormat::Auto,
    )
    .unwrap();

    assert!(result.output.ends_with("deck.pptx"));
    assert_eq!(result.slide_count, 2);

    let _ = std::fs::remove_dir_all(&root);
}

use ppt_rs::generator::images::ImageEffect;
use ppt_rs::generator::{Image, generate_image_xml};

#[test]
fn test_image_crop_xml() {
    let mut img = Image::new("test.png", 1000, 1000, "PNG");
    img = img.with_crop(0.1, 0.2, 0.3, 0.4);

    let xml = generate_image_xml(&img, 1, 1);

    // Check for srcRect with correct percentage values (0.1 -> 10000)
    assert!(xml.contains("<a:srcRect l=\"10000\" t=\"20000\" r=\"30000\" b=\"40000\"/>"));

    // Check structure
    assert!(xml.contains("<p:blipFill>"));
    assert!(xml.contains("<a:blip r:embed=\"rId1\"/>"));
}

#[test]
fn test_image_effect_shadow_xml() {
    let mut img = Image::new("test.png", 1000, 1000, "PNG");
